import 'package:json_annotation/json_annotation.dart';part 'approve_user_request.g.dart';@JsonSerializable()class ApproveUserRequest {  @JsonKey(name: 'target_user_id')  final int? targetUserId;  @JsonKey(name: 'role_id')  final int? roleId;  @JsonKey(name: 'approval_status')  final String? approvalStatus;  ApproveUserRequest({    this.targetUserId,    this.roleId,    this.approvalStatus,  });  factory ApproveUserRequest.fromJson(Map<String, dynamic> json) =>      _$ApproveUserRequestFromJson(json);  Map<String, dynamic> toJson() => _$ApproveUserRequestToJson(this);}